def get_filtered_catalog(model_key, cat_path='data/catalogues/catalogue_2007_2018.obj'):
    start_epoch = csep.utils.time_utils.strptime_to_utc_epoch(str(min(forecast_dates[model_key])))
    end_epoch = csep.utils.time_utils.strptime_to_utc_epoch(str(max(forecast_dates[model_key])))
    filters = [f'origin_time >= {start_epoch}', f'origin_time < {end_epoch}']
    with open(cat_path, 'rb') as obj:
        cat = pickle.load(obj)
    return cat.filter(filters)

