# 2. Universal sequence preparation function
def prep_sequence(start_date, end_date, models, min_mw=3.95):
    # Filter global catalogue
    with open('data/catalogues/catalogue_2007_2018.obj', 'rb') as obj:
        cat = pickle.load(obj)

    start_epoch = time_utils.strptime_to_utc_epoch(f'{start_date} 00:00:00.0')
    end_dt = pd.to_datetime(end_date) + pd.Timedelta(days=1)
    end_epoch = time_utils.strptime_to_utc_epoch(f'{end_dt.strftime("%Y-%m-%d")} 00:00:00.0')

    cat.filter(f'origin_time >= {start_epoch}')
    cat.filter(f'origin_time < {end_epoch}')
    if min_mw > 3.95:
        cat.filter(f'magnitude >= {min_mw}')

    epoch_times = cat.get_epoch_times()
    percentile = 95

    res_dfs, res_plow, res_phigh = {}, {}, {}

    for m in models:
        df, _, col_name = model_dicts[m]
        df_seq = df[(df['date'] >= start_date) & (df['date'] <= end_date)].copy()

        # Calculate obs counts
        obs_counts = []
        for i in range(len(df_seq)):
            d_start = time_utils.strptime_to_utc_epoch(f"{df_seq.date.values[i]} 00:00:00.0")
            d_end_dt = pd.to_datetime(df_seq.date.values[i]) + pd.Timedelta(days=1)
            d_end = time_utils.strptime_to_utc_epoch(f"{d_end_dt.strftime('%Y-%m-%d')} 00:00:00.0")
            obs_counts.append(np.sum((epoch_times >= d_start) & (epoch_times < d_end)))

        df_seq['obs'] = obs_counts

        # Calculate quantiles
        n_vals = df_seq[col_name].astype(float).values
        res_dfs[m] = df_seq
        res_plow[m] = stats.poisson.ppf((1 - percentile/100.)/2., n_vals)
        res_phigh[m] = stats.poisson.ppf(1 - (1 - percentile/100.)/2., n_vals)

    return res_dfs, res_plow, res_phigh

