joli_dates_list = []
tmps = []
tmp_dates_list = []

for i, (start, end) in enumerate(periods):
    period_dfs = []
    for df in base_models_per_period[i]:
        # Filter by date range
        mask = (df['date'] >= start) & (df['date'] < end) if i < 5 else (df['date'] >= start) & (df['date'] <= '2018-06-30')
        sliced_df = df[mask].copy()

        cols_to_keep = ['date'] + [col for col in sliced_df.columns if col.startswith('joli_') or col.startswith('n_')]
        period_dfs.append(sliced_df[cols_to_keep])

    # Merge all base models for this period
    merged_joli = period_dfs[0]
    for df in period_dfs[1:]:
        merged_joli = pd.merge(merged_joli, df, how="inner", on="date")

    jolis.append(merged_joli)
    joli_dates_list.append([datetime.strptime(d, '%Y-%m-%d') for d in merged_joli.date])

joli_1, joli_2, joli_3, joli_4, joli_5, joli_6 = jolis
joli_1dates, joli_2dates, joli_3dates, joli_4dates, joli_5dates, joli_6dates = joli_dates_list
